from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[2];M=R/'common_assets/nichijou_naze/management';c=json.loads((M/'catalog.v1.json').read_text());data=json.dumps(c,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>日常のなぜ？ 素材検索</title><style>body{font:16px sans-serif;color:#234b58;background:#f1f5f3;max-width:1200px;margin:24px auto;padding:16px}input,select{font:inherit;padding:10px;margin:6px}#cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}article{background:white;border-radius:16px;padding:18px}img{height:200px;max-width:100%;object-fit:contain}code{font-size:13px;word-break:break-all}a{color:#087f9b}h2{font-size:18px}.status{font-weight:bold}</style><h1>日常のなぜ？ 共通素材検索</h1><p>正本は既存manifestとlibrary-registry.json。このページは派生一覧です。制作前にCLIで最新のファイル・QCを照合してください。</p><input id="q" aria-label="用途・IDで検索" placeholder="考える / 光 / 吸引 / NNZ_"><select id="kind" aria-label="種類"><option value="">全種類</option><option>character</option><option>diagram</option><option>animation</option><option>layout</option><option>model</option><option>image</option></select><label><input id="ep" type="checkbox">EP専用も含める</label><p id="count"></p><main id="cards"></main><h2>計画・試作・未検品</h2><pre id="planned"></pre><script type="application/json" id="data">DATA</script><script>
const data=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id),url=p=>'../../../'+p.split('/').map(encodeURIComponent).join('/');
function draw(){el('cards').replaceChildren();const terms=el('q').value.toLowerCase().trim().split(/\\s+/).filter(Boolean);const rows=data.assets.filter(a=>(el('ep').checked||a.scope!=='episode')&&(!el('kind').value||a.kind===el('kind').value)&&terms.every(t=>[a.asset_id,a.name,a.kind,...a.tags].join(' ').toLowerCase().includes(t)));el('count').textContent=rows.length+'件 / 本番候補はQC・実在確認済みのみ。EP写真は通常検索から除外。';for(const a of rows){const card=document.createElement('article');const title=document.createElement('h2');title.textContent=a.name;card.append(title);const img=document.createElement('img');img.src=url(a.preview);img.alt=a.name;card.append(img);for(const text of [a.asset_id+' @ '+a.version,a.kind+' / '+a.scope,a.production_ready?'検品済み（制作時に再照合）':'利用停止・QC/ファイル確認必要']){const p=document.createElement('p');p.textContent=text;card.append(p)}const link=document.createElement('a');link.href=url(a.entrypoint);link.textContent='素材／コードを開く';card.append(link);const details=document.createElement('details'),sum=document.createElement('summary'),pre=document.createElement('pre');sum.textContent='パラメータ・権利・依存関係';pre.style.whiteSpace='pre-wrap';pre.textContent=JSON.stringify({api:a.api,runtime:a.runtime,parameters:a.parameter_schema,notes:a.parameters_note,dependencies:a.dependencies,rights:a.rights,qc:a.qc},null,2);details.append(sum,pre);card.append(details);el('cards').append(card)}}['q','kind','ep'].forEach(id=>el(id).addEventListener('input',draw));el('planned').textContent=[...data.planned,...data.candidates].map(a=>a.asset_id+' '+a.name+' ('+(a.status??'QC待ち')+')').join('\\n');draw();
</script></html>'''.replace('DATA',data)
(M/'catalog.html').write_text(page)
lines=['# 共通素材カタログ（自動生成）','','[操作方法](../../../docs/LIBRARY_OPERATIONS.md) / [ブラウザ検索](catalog.html)','','HTMLはダウンロード後に開くと用途・ID・種類で検索できます。GitHubでは以下の一覧を利用してください。','','|ID|版|用途|分類|検品|プレビュー|','|---|---|---|---|---|---|']
for a in c['assets']:
 lines.append('|'+ '|'.join([a['asset_id'],a['version'],a['name'],a['scope'],'済み' if a['production_ready'] else '停止',f"[画像](../../../{a['preview']})"] )+'|')
lines+=['','EP専用の写真・小道具は既存参照を維持しています。新EPでの常用候補はcommon/domainです。','未制作の台帳項目は候補としてのみ表示し、本番利用可能には含めません。']
(M/'CATALOG.md').write_text('\n'.join(lines)+'\n');print('Searchable catalog and GitHub list updated')
